/**
 * Every push/notification channel. These flow between `webContents.send`
 * (main→renderer) and `ipcRenderer.on`/`ipcRenderer.send` +
 * `ipcMain.on`/`ipcMain.emit` (renderer↔main one-way events).
 */
type IpcEventName =
  | 'appConfigUpdated'
  | 'app-notification'
  | 'app-notification-dismiss'
  | 'app-notification-ready'
  | 'controledMihomoConfigUpdated'
  | 'core-started'
  | 'core-status-changed'
  | 'core-stopped'
  | 'customTray:close'
  | 'groupsUpdated'
  | 'mihomoConnections'
  | 'mihomoLogs'
  | 'mihomoMemory'
  | 'mihomoTraffic'
  | 'overrideConfigUpdated'
  | 'override-install-confirm-result'
  | 'profileConfigUpdated'
  | 'profile-install-confirm-result'
  | 'quit-confirm-result'
  | 'renderer-content-ready'
  | 'rulesUpdated'
  | 'show-override-install-confirm'
  | 'show-profile-install-confirm'
  | 'show-quit-confirm'
  | 'trayIconUpdate'
  | 'updateFloatingWindow'
  | 'update-status'
  | 'updateTrayMenu'
